/**
 * Inline SVG icon library — the exact icon set used throughout
 * homepage.html (stroke-based, 24x24 viewBox, currentColor).
 *
 * Keeping these inline (vs. an icon font) avoids an extra HTTP request and
 * an extra library dependency, matching the reference design's own approach.
 *
 * @package Busly
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

