/**
 * Echo an icon by name — escaping is not applied because the source array
 * above is 100% static, developer-authored markup (no user input ever
 * reaches this function; see esc_html()/wp_kses() guidance in PHASE 6 which
 * applies to *dynamic* data, not compile-time icon constants).
 *
 * @param string $name Icon name (see keys in busly_get_icon_svg()).
 */
function busly_icon( $name ) {
	echo busly_get_icon_svg( $name ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
}
